def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        return float(min(budget, 18.0))

    prev_bids = []
    cindy_prev = None
    rich_alive = 0
    desperate_alive = 0

    for agent_id, opp in alive:
        if opp.get('budget', 0) >= 120:
            rich_alive += 1
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_alive += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
        if agent_id == 'Cindy' and bid is not None:
            cindy_prev = float(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))
    low_supply = supply <= 17.0
    high_supply = supply >= 22.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if hp <= 2 or no_water_days >= 2:
        emergency_bid = max(95.0, highest_prev + 6.0)
        if cindy_prev is not None:
            emergency_bid = max(emergency_bid, min(cindy_prev + 3.0, 175.0))
        return float(min(budget, emergency_bid))

    if rich_alive <= 1 and high_supply and danger == 0:
        return float(min(budget, 12.0))

    target = 0.0

    if cindy_prev is not None and cindy_prev >= 140.0:
        if danger == 0 and not low_supply:
            target = 14.0 if high_supply else 20.0
        elif danger >= 2 or low_supply:
            target = min(cindy_prev + 2.0, 172.0)
        else:
            target = 28.0
    else:
        base = 18.0 + (1.0 - scarcity) * 18.0
        pressure = min(highest_prev * 0.55 + avg_prev * 0.15, 65.0)
        target = max(base, pressure)
        if low_supply:
            target += 18.0
        if desperate_alive >= 2:
            target += 10.0

    if danger >= 2:
        target = max(target, highest_prev + 3.0, 72.0)
    elif danger == 1:
        target = max(target, 42.0)

    days_left = max(1, 10 - day)
    reserve_floor = days_left * 10.0
    spend_cap = budget - reserve_floor
    if spend_cap < 8.0:
        spend_cap = min(budget, max(8.0, budget * 0.35))

    if day >= 8 and hp > 4 and no_water_days == 0:
        target *= 0.9
    if day >= 9 and danger == 0:
        target = min(target, 22.0)

    bid = min(budget, spend_cap, target)
    bid = max(0.0, bid)
    return float(round(bid, 2))

