def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Collect yesterday's bids from opponents' previous_trace
    yesterday_bids = []
    for opp_id, opp in alive_opponents.items():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid as a fraction of salary
    base_bid = DAILY_SALARY * 0.5

    # Adjust based on yesterday's maximum bid
    if yesterday_bids:
        max_yesterday = max(yesterday_bids)
        # If there was a very high bid yesterday, be cautious
        if max_yesterday > DAILY_SALARY * 0.85:
            base_bid = DAILY_SALARY * 0.3
        else:
            # Slightly above yesterday's max to outbid if needed
            base_bid = max(base_bid, max_yesterday + 1.5)

    # Adjust for own health
    if hp <= 2:
        base_bid = DAILY_SALARY * 0.9
    elif hp <= 4:
        base_bid = DAILY_SALARY * 0.7

    # Ensure we don't exceed budget, and don't bid more than necessary
    bid = min(budget, base_bid)
    # If very low HP, bid even more aggressively
    if no_water_days > 0 and hp <= 2:
        bid = max(bid, DAILY_SALARY * 0.95)

    return min(budget, bid)
